const response = $input.first().json;
let rawContent = '';

if (response.choices && response.choices[0] && response.choices[0].message) {
  rawContent = response.choices[0].message.content;
} else {
  rawContent = JSON.stringify(response);
}

let data = {};
try {
  const cleanJson = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(cleanJson);
} catch (e) {
  data = {
    title: 'Strategi Optimasi Digital Advertising Berkelanjutan',
    content: '<p>' + rawContent + '</p>',
    category_id: 19,
    short_description: 'Panduan lengkap seputar strategi periklanan digital terkini.',
    meta_description: 'Pelajari teknik terbaru dalam optimasi iklan online untuk bisnis Anda.',
    meta_keywords: 'digital advertising, meta ads, scale up'
  };
}

// Cover image otomatis beresolusi tinggi
const coverImageUrl = 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&h=630&q=80';

return {
  title: data.title || 'Strategi Optimasi Iklan Digital',
  content: data.content || '<p>Konten artikel...</p>',
  short_description: data.short_description || '',
  meta_description: data.meta_description || '',
  meta_keywords: data.meta_keywords || 'digital advertising, ads, marketing',
  category_id: data.category_id || 19,
  image_url: coverImageUrl,
  author: 'Moh. Ali Murtado',
  display: '1'
};
